// Package pkgdirective reads forge's package-level comment directives —
// `//forge:exclude-contract: <why>`, `//forge:not-a-component: <why>` and
// their kin — from a package directory's source.
//
// It imports only the standard library, deliberately. Contract mock
// generation consults `//forge:exclude-contract`, and forge's own mocks are
// regenerated by internal/tools/mockgen WITHOUT building forge (forge#1261):
// a stale mock_gen.go in a package the forge binary imports must never stop
// the tool that refreshes it from compiling. So this package may not grow an
// import of anything that carries generated contract code;
// internal/tools/mockgen's TestMockgenImportsNoContractCodegen holds that.
//
// internal/codegen's directive API (FindExcludeContractMarker,
// FindNotAComponentMarker, …) is built on these primitives, so the generator
// and the bootstrap tool read a directive the same way.
package pkgdirective

import (
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Marker is one occurrence of a package directive that takes a reason —
// `//forge:exclude-contract: <why>` or `//forge:not-a-component: <why>`.
type Marker struct {
	// File is the absolute path of the file carrying the marker.
	File string
	// Line is the marker's 1-indexed line.
	Line int
	// Reason is the text after `forge:<directive>:`; "" for a bare marker.
	Reason string
}

// Find returns the first occurrence of a reasoned package directive
// (`//<directive>: <why>` or the bare `//<directive>`) in dir's non-test,
// non-generated files, scanned in name order. A reasoned occurrence anywhere
// wins over a bare one.
func Find(dir, directive string) (Marker, bool) {
	all := FindAll(dir, directive)
	for _, m := range all {
		if m.Reason != "" {
			return m, true
		}
	}
	if len(all) > 0 {
		return all[0], true
	}
	return Marker{}, false
}

// FindAll returns every occurrence of a reasoned package directive in dir's
// non-test, non-generated files, in file-name then line order.
func FindAll(dir, directive string) []Marker {
	var out []Marker
	ForEachPackageComment(dir, func(path string, line int, raw string) {
		if reason, ok := ParseReasoned(raw, directive); ok {
			out = append(out, Marker{File: path, Line: line, Reason: reason})
		}
	})
	return out
}

// ForEachPackageComment calls fn for every comment in dir's non-test,
// non-generated .go files, in file-name then position order. Unparseable
// files are skipped: a directive is read best-effort.
func ForEachPackageComment(dir string, fn func(path string, line int, raw string)) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	var names []string
	for _, e := range entries {
		n := e.Name()
		if e.IsDir() || !strings.HasSuffix(n, ".go") ||
			strings.HasSuffix(n, "_test.go") || strings.HasSuffix(n, "_gen.go") {
			continue
		}
		names = append(names, n)
	}
	sort.Strings(names)

	fset := token.NewFileSet()
	for _, n := range names {
		path := filepath.Join(dir, n)
		file, perr := parser.ParseFile(fset, path, nil, parser.ParseComments|parser.SkipObjectResolution)
		if perr != nil {
			continue
		}
		for _, cg := range file.Comments {
			for _, c := range cg.List {
				fn(path, fset.Position(c.Pos()).Line, c.Text)
			}
		}
	}
}

// ParseReasoned is the whole-line rule for a directive that takes a reason
// after a colon: `//<directive>: <why>` yields "<why>", the bare
// `//<directive>` yields "", and anything else — prose that mentions the
// directive, a different separator — is not the directive.
func ParseReasoned(raw, directive string) (reason string, ok bool) {
	text := TrimCommentMarkers(raw)
	if text == directive {
		return "", true
	}
	rest, has := strings.CutPrefix(text, directive+":")
	if !has {
		return "", false
	}
	return strings.TrimSpace(rest), true
}

// TrimCommentMarkers strips one comment's `//` or `/* */` syntax and the
// whitespace around its text.
func TrimCommentMarkers(raw string) string {
	switch {
	case strings.HasPrefix(raw, "//"):
		return strings.TrimSpace(strings.TrimPrefix(raw, "//"))
	case strings.HasPrefix(raw, "/*"):
		inner := strings.TrimPrefix(raw, "/*")
		inner = strings.TrimSuffix(inner, "*/")
		return strings.TrimSpace(inner)
	default:
		return strings.TrimSpace(raw)
	}
}
